function normalizeQuarters(raw,cutoff=new Date().toISOString().slice(0,10)){
 const tags={revenue:['RevenueFromContractWithCustomerExcludingAssessedTax','Revenues','SalesRevenueNet'],operating:['OperatingIncomeLoss'],net:['NetIncomeLoss'],cfo:['NetCashProvidedByUsedInOperatingActivities'],capex:['PaymentsToAcquirePropertyPlantAndEquipment']};
 const day=86400000,days=(start,end)=>(Date.parse(end)-Date.parse(start))/day+1,next=date=>new Date(Date.parse(date)+day).toISOString().slice(0,10),previous=date=>new Date(Date.parse(date)-day).toISOString().slice(0,10);
 const valid=f=>['10-K','10-K/A','10-Q','10-Q/A'].includes(f.form)&&f.filed<=cutoff&&f.end<=cutoff&&f.start&&Number.isFinite(f.val);
 const facts={};for(const [key,names]of Object.entries(tags))facts[key]=names.map(tag=>({tag,rows:(raw.facts?.['us-gaap']?.[tag]?.units?.USD||[]).filter(valid).sort((a,b)=>b.filed.localeCompare(a.filed)||b.accn.localeCompare(a.accn))}));
 const revenue=facts.revenue.flatMap(group=>group.rows.map(f=>({...f,tag:group.tag}))),annuals=new Map();
 for(const f of revenue)if(days(f.start,f.end)>=330&&days(f.start,f.end)<=380&&!annuals.has(f.start))annuals.set(f.start,{start:f.start,end:f.end});
 const annualList=[...annuals.values()].sort((a,b)=>a.start.localeCompare(b.start));if(!annualList.length)return {quarters:[],ttm:null,comparison:null,latestFiling:null};
 const latestAnnual=annualList.at(-1),lower=new Date(Date.parse(latestAnnual.end)-5*366*day).toISOString().slice(0,10);
 const fiscalStarts=[...annuals.keys(),next(latestAnnual.end)].sort();
 const fiscalStart=quarter=>fiscalStarts.filter(start=>start<=quarter.start&&days(start,quarter.end)<=380).at(-1);
 const anchors=new Map();
 for(const f of revenue){if(f.end<lower||days(f.start,f.end)<65||days(f.start,f.end)>110)continue;const existing=anchors.get(f.end);if(!existing||f.filed>existing.filed)anchors.set(f.end,{start:f.start,end:f.end,filed:f.filed});}
 for(const annual of annualList){if(annual.end<lower||anchors.has(annual.end))continue;const nine=revenue.filter(f=>f.start===annual.start&&days(f.start,f.end)>=240&&days(f.start,f.end)<=300&&days(next(f.end),annual.end)>=65&&days(next(f.end),annual.end)<=110).sort((a,b)=>b.end.localeCompare(a.end))[0];if(nine)anchors.set(annual.end,{start:next(nine.end),end:annual.end,filed:null});}
 const source=f=>({...f,url:'https://www.sec.gov/Archives/edgar/data/'+Number(raw.cik)+'/'+f.accn.replaceAll('-','')+'/'+f.accn+'-index.html'});
 function metric(key,quarter){
  for(const group of facts[key]){
   const direct=group.rows.find(f=>f.start===quarter.start&&f.end===quarter.end);
   if(direct)return {val:direct.val,method:'reported',tag:group.tag,sources:[source({...direct,tag:group.tag})]};
   const start=fiscalStart(quarter);if(!start||start===quarter.start)continue;
   const totals=group.rows.filter(f=>f.start===start&&f.end===quarter.end),priors=group.rows.filter(f=>f.start===start&&f.end===previous(quarter.start));
   if(!totals.length||!priors.length)continue;
   let total=totals[0],prior=priors[0];
   const matched=totals.map(t=>({t,p:priors.find(p=>p.accn===t.accn)})).find(pair=>pair.p);
   if(matched){total=matched.t;prior=matched.p;}
   return {val:total.val-prior.val,method:'derived',tag:group.tag,crossFiling:total.accn!==prior.accn,sources:[source({...total,tag:group.tag}),source({...prior,tag:group.tag})],formula:'Current cumulative total minus earlier cumulative total with the same fiscal start and XBRL tag.'};
  }return null;
 }
 const quarters=[...anchors.values()].sort((a,b)=>a.end.localeCompare(b.end)).map(q=>({start:q.start,end:q.end,facts:Object.fromEntries(Object.keys(tags).map(key=>[key,metric(key,q)]))})).filter(q=>q.facts.revenue).slice(-12);
 const last=quarters.at(-1);
 const comparison=last?quarters.filter(q=>days(q.end,last.end)>=350&&days(q.end,last.end)<=385&&Math.abs(days(q.start,q.end)-days(last.start,last.end))<=10).sort((a,b)=>Math.abs(days(a.end,last.end)-366)-Math.abs(days(b.end,last.end)-366))[0]||null:null;
 const four=quarters.slice(-4),contiguous=four.length===4&&four.every((q,i)=>!i||q.start===next(four[i-1].end))&&days(four[0].start,four[3].end)>=330&&days(four[0].start,four[3].end)<=380;
 const ttm=contiguous?{start:four[0].start,end:four[3].end,facts:Object.fromEntries(Object.keys(tags).map(key=>[key,four.every(q=>q.facts[key])?{val:four.reduce((n,q)=>n+q.facts[key].val,0),method:'sum',sources:four.flatMap(q=>q.facts[key].sources)}:null]))}:null;
 if(ttm){
  ttm.reconciliation={};
  for(const key of Object.keys(tags)){
   if(!ttm.facts[key])continue;
   const annual=facts[key].map(group=>group.rows.find(f=>f.start===ttm.start&&f.end===ttm.end)).find(Boolean);
   if(annual){const agrees=Math.abs(ttm.facts[key].val-annual.val)<=Math.max(1,Math.abs(annual.val)*.000001);ttm.reconciliation[key]=agrees?'Matches annual total':'Withheld: quarter sum differs from the reported annual total';if(!agrees)ttm.facts[key]=null;}
  }
 }
 const latestFiling=revenue.filter(f=>days(f.start,f.end)>=65).sort((a,b)=>b.filed.localeCompare(a.filed))[0];
 return {quarters,comparison,ttm,latestFiling:latestFiling?{filed:latestFiling.filed,form:latestFiling.form,end:latestFiling.end,url:source(latestFiling).url}:null,notes:['Quarter-only figures use exact periods of 65–110 days.','When no quarter-only fact is available, cumulative totals are subtracted only within the same fiscal start and tag. Q4 may be annual total minus nine months.','Latest eligible facts are preferred. Derived values may combine different filings; restatements can affect comparability.','At an annual boundary, TTM sums are checked against matching reported annual totals when available. Disagreeing metrics are withheld.','Trailing 12 months (TTM) requires four consecutive quarters covering 330–380 days. Any metric with missing quarters remains unavailable.','Same-quarter comparison uses a comparable duration ending approximately one year earlier, allowing 52/53-week fiscal calendars.']};
}

const TAGS = {
 interest:['InterestExpenseNonoperating','InterestExpense'], leaseInterest:['FinanceLeaseInterestExpense'], dividends:['PaymentsOfDividendsCommonStock'], buybacks:['PaymentsForRepurchaseOfCommonStock'], operatingLeases:['OperatingLeaseLiability'], financeLeases:['FinanceLeaseLiability'], maturity1:['LongTermDebtMaturitiesRepaymentsOfPrincipalInNextTwelveMonths'], maturity2:['LongTermDebtMaturitiesRepaymentsOfPrincipalInYearTwo'], maturity3:['LongTermDebtMaturitiesRepaymentsOfPrincipalInYearThree'], maturity4:['LongTermDebtMaturitiesRepaymentsOfPrincipalInYearFour'], maturity5:['LongTermDebtMaturitiesRepaymentsOfPrincipalInYearFive'], maturityAfter5:['LongTermDebtMaturitiesRepaymentsOfPrincipalAfterYearFive'],
 revenue:['RevenueFromContractWithCustomerExcludingAssessedTax','Revenues','SalesRevenueNet'],
 pretax:['IncomeLossFromContinuingOperationsBeforeIncomeTaxesExtraordinaryItemsNoncontrollingInterest','IncomeLossFromContinuingOperationsBeforeIncomeTaxesMinorityInterestAndIncomeLossFromEquityMethodInvestments'], incomeTax:['IncomeTaxExpenseBenefit'], cost:['CostOfRevenue','CostOfGoodsAndServicesSold'], research:['ResearchAndDevelopmentExpense'], selling:['SellingGeneralAndAdministrativeExpense'], operating:['OperatingIncomeLoss'], net:['NetIncomeLoss'], cfo:['NetCashProvidedByUsedInOperatingActivities'], capex:['PaymentsToAcquirePropertyPlantAndEquipment'],
 cash:['CashAndCashEquivalentsAtCarryingValue'], investments:['ShortTermInvestments'], debtCurrent:['LongTermDebtCurrent','LongTermDebtAndCapitalLeaseObligationsCurrent'], debtLong:['LongTermDebtNoncurrent'], shortDebt:['ShortTermBorrowings'], shares:['CommonStockSharesOutstanding'], eps:['EarningsPerShareDiluted'], assets:['Assets'], sbc:['ShareBasedCompensation']
};
function normalize(raw,ticker,meta={}) {
 const gaap=raw.facts?.['us-gaap']; if(!gaap) throw Error('US GAAP financial facts are unavailable. This version supports US GAAP filers.');
 const cutoff=new Date().toISOString().slice(0,10);
 function pick(key,end,start) {
  const unit=key==='shares'?'shares':key==='eps'?'USD/shares':'USD';
  for(const tag of TAGS[key]) {
   const list=(gaap[tag]?.units?.[unit]||[]).filter(f=>['10-K','10-K/A','10-Q','10-Q/A'].includes(f.form)&&f.filed<=cutoff&&f.end===end&&(start?f.start===start:!f.start));
   list.sort((a,b)=>b.filed.localeCompare(a.filed));
   if(list.length){const f=list[0];return {...f,tag,url:'https://www.sec.gov/Archives/edgar/data/'+Number(raw.cik)+'/'+f.accn.replaceAll('-','')+'/'+f.accn+'-index.html'};}
  }return null;
 }
 const periods=new Map();
 for(const tag of TAGS.revenue) for(const f of gaap[tag]?.units?.USD||[]) {
  const days=(Date.parse(f.end)-Date.parse(f.start))/86400000;
  if(['10-K','10-K/A'].includes(f.form)&&f.filed<=cutoff&&days>=330&&days<=380) periods.set(f.end,{start:f.start,end:f.end});
 }
 const years=[...periods.values()].sort((a,b)=>a.end.localeCompare(b.end)).slice(-5).map(p=>{
  const facts={}; for(const k of Object.keys(TAGS))facts[k]=pick(k,p.end,['cash','investments','debtCurrent','debtLong','shortDebt','shares','assets','operatingLeases','financeLeases','maturity1','maturity2','maturity3','maturity4','maturity5','maturityAfter5'].includes(k)?null:p.start);
  return {...p,label:'FY '+p.end.slice(0,4),facts};
 });
 if(years.length<2)throw Error('At least two comparable annual revenue periods are required.');
 return {ticker,name:raw.entityName,cik:raw.cik,years,retrieved:new Date().toISOString(),quarterly:normalizeQuarters(raw),sic:meta.sic||'',industry:meta.sicDescription||'',segments:[],notes:['Annual values use 330–380 day periods; metrics must match the revenue period exactly.','Latest eligible filing for each metric is used; comparative figures may be restated. Different metrics may cite different filings.','The company-facts feed omits segment dimensions. Separate annual-filing enrichment is shown when available; operating KPI coverage varies.','Annual figures anchor valuation; quarterly and trailing results are shown separately. Consensus forecasts are not included.']};
}
function dcf(data,a){
 if(!['growth','margin','tax','reinvest','discount','terminal'].every(k=>Number.isFinite(a[k])))throw Error('All model assumptions must be finite numbers.');
 const last=data.years.at(-1), v=k=>last.facts[k]?.val;
 if(!(v('revenue')>0)||!(a.discount>a.terminal))throw Error('Discount rate must exceed terminal growth.');
 let revenue=v('revenue'),pv=0;const rows=[];
 for(let i=1;i<=5;i++){revenue*=1+a.growth;const nopat=revenue*a.margin*(1-a.tax),reinvestment=revenue*a.reinvest,fcff=nopat-reinvestment,discounted=fcff/(1+a.discount)**i;pv+=discounted;rows.push({year:Number(last.end.slice(0,4))+i,revenue,nopat,reinvestment,fcff,discounted});}
 if(rows.at(-1).fcff<=0)throw Error('Terminal cash flow must be positive. Adjust operating margin or reinvestment.');
 const terminal=rows.at(-1).fcff*(1+a.terminal)/(a.discount-a.terminal)/(1+a.discount)**5,ev=pv+terminal;
 const cash=v('cash'),long=v('debtLong'),current=v('debtCurrent'),shares=v('shares');
 const ready=[cash,long,current,shares].every(Number.isFinite)&&shares>0;
 const debt=ready?long+current+(v('shortDebt')||0):null;
 const equity=ready?ev+cash+(v('investments')||0)-debt:null;
 return {rows,ev,equity,perShare:equity===null?null:equity/shares,terminalShare:terminal/ev,terminal,cash,shares,debt};
}

function selectBusinessProfile(data,profiles){
 const latest=data.years.at(-1);if(!latest)return null;
 const profile=profiles.find(p=>Number(p.cik)===Number(data.cik)&&p.periodEnd===latest.end);
 if(!profile||!Number.isFinite(latest.facts.revenue?.val)||Math.abs(profile.totalRevenue-latest.facts.revenue.val)>1)return null;
 const valid=profile.views.filter(view=>reconcilesSegments(view.segments,profile.totalRevenue));
 return valid.length?{...profile,views:valid}:null;
}
function reconcilesSegments(segments,total){
 return Number.isFinite(total)&&total>0&&segments.length>=2&&segments.every(s=>Number.isFinite(s.revenue)&&s.revenue>=0)&&new Set(segments.map(s=>s.name)).size===segments.length&&Math.abs(segments.reduce((n,s)=>n+s.revenue,0)-total)<=Math.max(1,total*0.000001);
}
// Conservative inline-XBRL extraction: one dimension, exact annual period,
// standard revenue tag, USD units, unique members, and a reconciled total.
function extractSegmentViews(html,period,totalRevenue){
 const attrs=s=>Object.fromEntries([...s.matchAll(/([\w:-]+)\s*=\s*["']([^"']*)["']/g)].map(m=>[m[1].toLowerCase(),m[2]]));
 const text=s=>s.replace(/<[^>]*>/g,'').replace(/&nbsp;|&#160;/g,' ').trim();
 const tagText=(s,tag)=>s.match(new RegExp('<(?:[\\w-]+:)?'+tag+'\\b[^>]*>([\\s\\S]*?)<\\/(?:[\\w-]+:)?'+tag+'>','i'))?.[1]?.trim();
 const units=new Set();for(const m of html.matchAll(/<(?:[\w-]+:)?unit\b([^>]*)>([\s\S]*?)<\/(?:[\w-]+:)?unit>/gi))if(/:(?:USD)\s*<\//i.test(m[2])&&!/divide/i.test(m[2]))units.add(attrs(m[1]).id);
 const contexts=new Map();
 for(const m of html.matchAll(/<(?:[\w-]+:)?context\b([^>]*)>([\s\S]*?)<\/(?:[\w-]+:)?context>/gi)){
  if(tagText(m[2],'startDate')!==period.start||tagText(m[2],'endDate')!==period.end)continue;
  const members=[...m[2].matchAll(/<(?:[\w-]+:)?explicitMember\b([^>]*)>([^<]+)<\/(?:[\w-]+:)?explicitMember>/gi)];
  if(members.length!==1||/<(?:[\w-]+:)?typedMember\b/i.test(m[2]))continue;
  const member=members[0],axis=attrs(member[1]).dimension;
  if(!/(StatementBusinessSegmentsAxis|ProductOrServiceAxis|GeographicalAxis)$/.test(axis||''))continue;
  contexts.set(attrs(m[1]).id,{axis,member:member[2].trim()});
 }
 const groups=new Map();
 for(const m of html.matchAll(/<ix:nonFraction\b([^>]*)>([\s\S]*?)<\/ix:nonFraction>/gi)){
  const a=attrs(m[1]),context=contexts.get(a.contextref);if(!context||!units.has(a.unitref)||a['xsi:nil']==='true')continue;
  if(!/^us-gaap:(RevenueFromContractWithCustomerExcludingAssessedTax|Revenues|SalesRevenueNet)$/.test(a.name||''))continue;
  if(a.format&&!/num-dot-decimal|numdotdecimal|numdash|zerodash/i.test(a.format))continue;
  const raw=text(m[2]).replace(/,/g,'').trim();if(!/^-?\d+(\.\d+)?$/.test(raw))continue;
  const scale=Number(a.scale||0);if(!Number.isInteger(scale)||Math.abs(scale)>12)continue;
  const revenue=Number(raw)*10**scale*(a.sign==='-'?-1:1);if(!Number.isFinite(revenue)||revenue<0)continue;
  const key=context.axis+'|'+a.name;if(!groups.has(key))groups.set(key,new Map());
  const group=groups.get(key),existing=group.get(context.member);
  if(existing&&existing.revenue!==revenue){group.conflict=true;continue;}
  const name=context.member.split(':').at(-1).replace(/Member$/,'').replace(/([a-z\d])([A-Z])/g,'$1 $2').replace(/([A-Z])([A-Z][a-z])/g,'$1 $2');
  group.set(context.member,{name,revenue,member:context.member,tag:a.name,contextId:a.contextref,description:'Category reported in the filing. A plain-language description has not yet been reviewed.',driver:null});
 }
 const views=[],seenAxes=new Set();for(const [key,group] of groups){const axis=key.split('|')[0],segments=[...group.values()];if(group.conflict||seenAxes.has(axis)||!reconcilesSegments(segments,totalRevenue))continue;seenAxes.add(axis);views.push({id:'filing-'+views.length,label:/BusinessSegments/.test(axis)?'Business segments':/ProductOrService/.test(axis)?'Products & services':'Geographic breakdown',kind:'Reported revenue dimension · '+axis,segments});}
 return views;
}

